mapper.sql:
FROM check_report r
INNER JOIN check_task t ON t.id = r.task_id AND t.is_deleted = 0
INNER JOIN paper_info p ON p.id = t.paper_id AND p.is_deleted = 0
LEFT JOIN sys_user u ON u.id = p.student_id AND u.is_deleted = 0
WHERE r.is_deleted = 0

    AND p.paper_title LIKE CONCAT('%', #{paperTitle}, '%')


    AND u.real_name LIKE CONCAT('%', #{studentName}, '%')


    AND t.check_status = #{checkStatus}


    AND t.check_rate >= #{minSimilarity}


    AND t.check_rate <= #{maxSimilarity}



    AND 1 = 0


    AND p.college_id = #{scope.collegeId}


    AND p.major_id = #{scope.majorId}


    AND p.teacher_id = #{scope.teacherId}


    AND p.student_id = #{scope.studentId}
